from common_e15 import *
import pandas as pd,numpy as np,re

def md(frame,limit=None):
 if not isinstance(frame,pd.DataFrame):frame=pd.DataFrame(frame)
 if limit is not None:frame=frame.head(limit)
 cols=list(frame.columns)
 def fmt(v):
  if isinstance(v,(float,np.floating)):return 'null' if pd.isna(v) else f'{v:.7g}'
  return str(v).replace('|','/').replace('\n',' ')
 return '| '+' | '.join(cols)+' |\n| '+' | '.join(['---']*len(cols))+' |\n'+''.join('| '+' | '.join(fmt(v) for v in row)+' |\n' for row in frame.itertuples(index=False,name=None))+'\n'

def main():
 audit=read(R/'18_independent_verification/INDEPENDENT_PASS.json');assert audit['passed'];verify_protocol();df=pd.read_csv(R/'SOURCE_LEVEL_FIELD_METRICS.csv');means=pd.read_csv(R/'15_plate_level_metrics/ARITHMETIC_SEED_METRIC_MEANS.csv');seeds=pd.read_csv(R/'15_plate_level_metrics/SEED_MACRO_METRICS.csv');plates=pd.read_csv(R/'PLATE_LEVEL_FIELD_METRICS.csv');vari=pd.read_csv(R/'CONTEXT_PREDICTION_VARIATION.csv');matches=pd.read_csv(R/'BOUNDARY_INTERIOR_MATCHED_COMPARISONS.csv');bounds=pd.read_csv(R/'BOUNDARY_JUMP_METRICS.csv');inside=pd.read_csv(R/'INTERIOR_JUMP_METRICS.csv');budget=read(R/'INFERENCE_EXECUTION_BUDGET.json');replay=read(R/'05_original_prediction_replay/ALL_REPLAY_PASS.json');feature=pd.read_csv(R/'FEATURE_NORMALIZATION_DIFFERENCES.csv');rawreg=rows(R/'21_reproducibility/REPLAY_REGISTRY.csv')+rows(R/'21_reproducibility/INTERVENTION_REGISTRY.csv');contextmean=vari.groupby(['model','condition','policy','plate'])[['mean_signed_difference_MPa','mean_absolute_difference_MPa','RMS_difference_MPa','Q95_absolute_difference_MPa','maximum_difference_MPa']].mean().groupby(['model','condition','policy']).mean().reset_index();table(R/'17_mechanism_decomposition/EQUAL_PLATE_CONTEXT_VARIATION.csv',contextmean.to_dict('records'))
 continuity=matches.groupby(['model','seed','condition','policy','plate'])[['mean_boundary_jump_error_MPa','mean_matched_interior_jump_error_MPa','boundary_minus_matched_error_MPa','mean_boundary_pred_jump_MPa','mean_boundary_ref_jump_MPa']].mean().groupby(['model','seed','condition','policy']).mean().reset_index();cmean=continuity.groupby(['model','condition','policy']).mean(numeric_only=True).reset_index().drop(columns=['seed']);table(R/'15_plate_level_metrics/SEED_CONTINUITY_MACROS.csv',continuity.to_dict('records'));table(R/'15_plate_level_metrics/ARITHMETIC_SEED_CONTINUITY_MEANS.csv',cmean.to_dict('records'))
 paired=[]
 for _,a in df.iterrows():
  if a.policy=='S0':continue
  b=df[(df.model==a.model)&(df.seed==a.seed)&(df.source_id==a.source_id)&(df.condition==a.condition)&(df.policy=='S0')].iloc[0];paired.append(dict(model=a.model,seed=int(a.seed),source_id=a.source_id,plate=a.plate,condition=a.condition,policy=a.policy,delta_L2=a.L2-b.L2,delta_MAE_MPa=a.MAE_MPa-b.MAE_MPa,delta_high95_IoU=a.high95_IoU-b.high95_IoU,delta_Kmax_error=a.Kmax_error-b.Kmax_error,oracle=a.policy=='ORACLE'))
 paired=pd.DataFrame(paired);table(R/'14_source_level_metrics/PAIRED_SOURCE_DIFFERENCES.csv',paired.to_dict('records'));table(R/'15_plate_level_metrics/PAIRED_PLATE_DIFFERENCES.csv',paired.groupby(['model','seed','plate','condition','policy'])[['delta_L2','delta_MAE_MPa','delta_high95_IoU','delta_Kmax_error']].mean().reset_index().to_dict('records'))
 oracle_rms=float(vari[vari.policy=='ORACLE'].RMS_difference_MPa.mean());sampling_rms=float(vari[(vari.policy=='SHIFT')&(vari.condition=='FULL')].RMS_difference_MPa.mean());restricted=matches[(matches.policy=='S0')&matches.condition.isin(['X50','X43'])];positive=int((restricted.boundary_minus_matched_error_MPa>0).sum());allmatches=len(restricted);seam_supported=all(restricted.groupby(['model','seed','condition']).boundary_minus_matched_error_MPa.mean()>0);deltaweight=[]
 for _,a in means[means.policy=='S2'].iterrows():
  b=means[(means.model==a.model)&(means.condition==a.condition)&(means.policy=='S1')].iloc[0];deltaweight.append(abs(a.L2-b.L2))
 matrix=[dict(mechanism='M1 window-dependent global feature block',controlled_variable='only nine centered-coordinate/global-statistic channels; physical points and visible local neighbors/context IDs fixed',held_constant='weights, source IDs/XYZ, T0, target, visible support, query ownership and sampled context IDs',actual_intervention='ORACLE_FULL_GEOMETRY_DIAGNOSTIC replaces channels0/1/2/6/7/8/16/17/18',measured_signature=f'mean source/seed/condition RMS shift {oracle_rms:.9g} MPa',classification='CONTROLLED_COMPUTATIONAL_EFFECT_SUPPORTED' if oracle_rms>1e-4 else 'NO_SUPPORT_IN_TESTED_CONDITIONS',confounders='nine channels move jointly; full hidden statistics are oracle-only; no individual feature or deployable NORM-P isolated',permitted_conclusion='frozen predictor responds to the supplied global-feature block, not proof of superior physical normalization'),dict(mechanism='M2 loss of geometric context',controlled_variable='FULL/X50/X43 visible geometry extent',held_constant='checkpoint, source identities and target support',actual_intervention='crop measured vertices and fully visible original triangles; recompute representation',measured_signature='source/seed S0 contrasts and oracle residual errors retained',classification='MECHANISM_NOT_ISOLATED',confounders='visible local features, global feature statistics and sampled context set move jointly',permitted_conclusion='restricted-observation computational sensitivity established; pure information-loss effect not isolated'),dict(mechanism='M3 sampled context point variation',controlled_variable='FULL area-CDF phase .5 to .75; exactly4096 unique IDs',held_constant='full feature tensor, measured extent, local neighbors, weights and original queries',actual_intervention='FULL SHIFT sampling-only control',measured_signature=f'mean source/seed RMS shift {sampling_rms:.9g} MPa',classification='CONTROLLED_COMPUTATIONAL_EFFECT_SUPPORTED' if sampling_rms>1e-4 else 'NO_SUPPORT_IN_TESTED_CONDITIONS',confounders='one deterministic sampling phase only; D0 is a separate nonuniform partial control',permitted_conclusion='finite frozen-model sensitivity to this exact selected context set'),dict(mechanism='M4 query-tile ownership variation',controlled_variable='original hard query ownership versus expanded query support',held_constant='source geometry/checkpoint for each original context',actual_intervention='25% query overlap around original centers',measured_signature=f'{positive}/{allmatches} source-seed-width baseline boundary/control contrasts positive',classification='DESCRIPTIVE_ASSOCIATION_ONLY' if seam_supported else 'MECHANISM_NOT_ISOLATED',confounders='ownership, multiple raw coverage and context contributors move jointly relative to S0; FULL has no original seams',permitted_conclusion='restricted-boundary association does not prove ownership alone causes error'),dict(mechanism='M5 deterministic stitching weighting',controlled_variable='S1 uniform versus S2 tent weights on identical cached raw arrays',held_constant='every raw prediction, query ID, context, checkpoint and target',actual_intervention='partition of unity; floor1e-6; every contributor retained',measured_signature=f'max absolute equal-plate L2 S2-minus-S1 difference {max(deltaweight):.9g}',classification='CONTROLLED_COMPUTATIONAL_EFFECT_SUPPORTED' if max(deltaweight)>1e-9 else 'NO_SUPPORT_IN_TESTED_CONDITIONS',confounders='supports attribution to weighting only; S0 comparison additionally changes raw support; smoothness is not accuracy',permitted_conclusion='weighting computational effect is isolated; joint continuity/localization/amplitude results determine benefit'),dict(mechanism='M6 intrinsic frozen-model context dependence',controlled_variable='same point under prescribed shifted visible contexts',held_constant='canonical ID and physical XYZ, checkpoint, width and V1 reference',actual_intervention='one +2mm shift; bounds clipped independently; no target guidance',measured_signature=f'paired original-area metrics for {int(vari[vari.policy=="SHIFT"].matched_points.sum())} source-point/checkpoint/width comparisons',classification='CONTROLLED_COMPUTATIONAL_EFFECT_SUPPORTED',confounders='in restricted contexts inputs/features/sampling all change; attention submechanism not isolated',permitted_conclusion='same-point context dependence under precisely this protocol, not a material-failure mechanism')]
 table(R/'MECHANISM_EVIDENCE_MATRIX.csv',matrix)
 operational=means[means.policy.isin(['S0','S1','S2'])][['model','condition','policy','L2','MAE_MPa','high95_IoU','high95_FN_area_mm2','Kmax_error','Q95_error_MPa','pred_std_MPa']];seedtable=seeds[seeds.policy.isin(['S0','S1','S2'])][['model','seed','condition','policy','L2','MAE_MPa','high95_IoU']]
 sections={}
 sections['scope']='This is an EXPLORATORY_MECHANISM_AUDIT on thirteen already examined numerical sources from five documentary plates C/E/G/H/X and both original seeds20261021/20261022. No new independent cohort, physical validation, neural fit, optimizer step, FE solve/mesh/target or external inference is introduced. The V1 M2 target, original IDs, measured XYZ, T0 weights, frozen T2 core, 100MPa X-tension assumption, E210GPa/nu0.30 and assumed planar rear remain unchanged. Predictions are elastic numerical surrogates; welding residual stress, plasticity, crack growth and fatigue-life validation are outside this evidence.\n'
 sections['integrity']=f'Historical release hashes: **{read(R/"00_historical_integrity/INTEGRITY_PASS.json")["historical_release_files"]} PASS**. Thirteen qualified target packages, twenty checkpoints, original T0/XYZ/areas and folds agree. Every loaded model has7228 parameters, nineteen features, width24, one multiscale block and4096 context points; architecture source matches released files. All156 historical FULL/X50/X43 fields replay at exact source IDs with maximum discrepancy **{replay["max_difference_MPa"]:.9g}MPa**, tolerance1e-4MPa. Historical target/checkpoint33 SHA256 values were rechecked after execution.\n'
 sections['tiles']='Historical FULL calls a single full feature/context object; query batches512 do not create physical observation tiles and the network has no query-query interaction. Its actual owner ID is0 everywhere. X50/X43 use five hard query ownership bins from saved original tile_id, with separately centered/clipped observation windows. There was no overlapping averaging or learned stitching. The nominal spacing is8mm, final bin may be narrower; actual bounds are exported per source. The four old geometric lines in FULL are diagnostic reference cuts, **not actual inference seams**. Original-to-output source ordering is retained.\n\n'+md(pd.read_csv(R/'ORIGINAL_TILE_TOPOLOGY.csv')[['source_id','tile','center_X_mm','query_X_min_mm','query_X_max_mm','query_points']],limit=15)
 sections['context']='The shifted restricted window center is +2mm (25% of nominal8mm query spacing); each bound clips to the measured source rectangle without recentering. All original core points remain queried. FULL has no second different full physical extent, so its paired control changes only area-CDF sampling phase .5 to .75 with4096 unique points and identical features/local neighborhoods. Restricted shifts jointly change visible input geometry, its representation and sampled context IDs; do not call this pure sampling or isolated geometry-information loss.\n\n'+md(contextmean)
 sections['features']='The actual nineteen channels are centered XYZ/60mm(0–2), visible area-normalized surface normal(3–5), visible XYZ spans/60mm(6–8), fixed X load axis(9–11), front tag0(12), local16-neighbor height relief in mm(13), local normal variation(14), log1p visible incident area(15), visible normalX/Y standard deviations(16–17), and duplicate Z span/60mm(18). The /60mm scale is fixed historically; the centering and global statistics change with observation. Channels0–2 can change from centering alone at unchanged physical XYZ. Span and normal-statistic changes are properties of available support, not mere unit conversion. Channel13 is local height relief, **not a measured parent-plane-relative toe height**. No feature was silently redefined.\n\n130 original visible windows and130 shifted windows were checked through separate geometry/formula paths. Detailed same-point values use a geometry-only128-per-tile sample; distribution summaries use all original assigned query points.\n\n'+md(feature.groupby(['condition','channel'])[['RMS_change','maximum_change','affected_points']].mean().reset_index())
 sections['normalization']='NORM-V exactly reproduces historical visible-window preprocessing. A complete NORM-P replacement is **INFEASIBLE**: independent physical/design datums and substitutes for measured relief/normal statistics are not documented sufficiently; arbitrary constants were not invented. Consequently no NORM-P predictions exist. The separately labeled ORACLE_FULL_GEOMETRY_DIAGNOSTIC replaces only global block0/1/2/6/7/8/16/17/18 with full-information values at the same visible points, keeping local neighbors, visible context IDs, query ownership and checkpoint fixed. It isolates this joint feature-block intervention, not any one channel or scalar-normalization factor. It deliberately accesses hidden geometry and is excluded from operational partial-view comparisons. It is an input-distribution counterfactual, not a deployable validated policy.\n\n'+md(contextmean[contextmean.policy=='ORACLE'])
 sections['information']='The FULL/X50/X43 contrasts preserve original reference support and area weights. They jointly change available shape information, global descriptors, visible-normal/local features near context edges and deterministic context membership. The oracle block removes one measured representation difference but does not fix all local feature support or sampled context changes. Residual error therefore does not uniquely identify pure information loss. Original D0 retains full visible features/neighbors but concentrates4080/4096 context points in a crop with16 outside; it is a partial nonuniform density control, not factorial isolation.\n\n'+md(means[means.policy.isin(['S0','ORACLE'])][['model','condition','policy','L2','MAE_MPa','high95_IoU']])
 sections['boundaries']='Canonical adjacency comes from unique original T0 triangle edges whose endpoints both belong to the frozen valid core; physical3D separation and source IDs are saved. All edge orientations are evaluated in secondary tables; primary seam/control comparisons use horizontal X edges at the same Y, matching the old diagnostic. Edge statistics count edges equally; field metrics retain original T0 areas. A boundary is classified by actual saved ownership, never by stress size. Restricted original boundaries remain fixed comparison locations after blending; overlap output itself has multiple owners. FULL has no original boundary, and its corresponding five-line statistics are explicitly proxy cuts.\n\nGeometry-only interior matching uses standardized physical separation, measured height, normal-based slope, curvature proxy, relative X/Y and distance from a maximum-slope geometric ridge. Matching uses replacement; unique control counts and distance diagnostics are exported. A separate posthoc evaluation also matches FE reference-gradient magnitude; it never enters inference. Signed excess=abs(deltaP)-abs(deltaT2) is retained, including negative values. Jump error=abs(deltaP-deltaT2).\n\n'+md(cmean[cmean.policy=='S0'])+f'Baseline restricted boundary/control mean error contrasts are positive in{positive}/{allmatches} correlated source-seed-width cases. Repeated point comparisons do not create independent replicates.\n'
 sections['stitching']='One fixed25% query overlap expands each original query support by1mm at both sides, clipped to frozen core bounds, producing2mm overlap between nominal8mm-spaced query tiles. Original centers and physical observation-width rules remain unchanged. S0 reproduces old raw hard ownership. S1 averages every valid expanded-query raw contributor. S2 uses max(1e-6,1-abs(X-center)/(actual query half-span+1mm)), then normalizes across every contributor. S1/S2 consume **identical cached raw predictions**. S0-to-overlap also changes query coverage/contributing contexts, so that contrast is not weighting alone. FULL contributors share a single feature/context object; this is a batch/regrouping control.\n\n'+md(operational)+'\n## Continuity at fixed historical seam/proxy locations\n\n'+md(cmean[cmean.policy.isin(['S0','S1','S2'])])
 sections['weights']='All312 source/model/seed/condition stitching outputs retain every original34200-point core. Each actual raw contributor has original source/checkpoint/tile provenance. Nonnegative finite weights sum to1 within1e-12 per source point; no stress, FE label, threshold, policy-specific context resampling or post-aggregation spatial filter enters weighting. Independently reconstructed weighted sums reproduce saved outputs.\n\n'+md(pd.read_csv(R/'STITCHING_WEIGHT_VALIDATION.csv').groupby('policy')[['raw_predictions','multiple_prediction_points','minimum_weight','maximum_weight','maximum_sum_error']].agg({'raw_predictions':'sum','multiple_prediction_points':'sum','minimum_weight':'min','maximum_weight':'max','maximum_sum_error':'max'}).reset_index())
 sections['accuracy']='Metrics use original T0 weights and original core: L2=sqrt(sum w(p-T2)^2/sum wT2^2); MAE/RMSE/bias retain MPa. High95 uses separately computed area-weighted CDF-interpolated95th-percentile thresholds, >= inclusion, weighted intersection/union, precision/recall and original-coordinate centroid distances. Peak and Q95 biases and predicted/reference variance accompany smoothness. Worst regional L2 uses the frozen target region labels. Source scores average within each documentary plate, then five plates equally; both seeds and their arithmetic metric means are retained, without prediction ensembling.\n\n'+md(seedtable)+'\n## Peak and hotspot safeguards\n\n'+md(means[means.policy.isin(['S0','S1','S2'])][['model','condition','policy','high95_FN_area_mm2','Kmax_error','Q95_error_MPa','pred_std_MPa','ref_std_MPa']])
 sections['heterogeneity']='Every source/plate/seed is retained. PAIRED_SOURCE_DIFFERENCES and PAIRED_PLATE_DIFFERENCES compare each execution against its matching model/seed/condition S0. A gain in aggregate L2 may coexist with localization or peak-amplitude degradation. No favorable seed or production policy is selected.\n\n'+md(paired.groupby(['model','condition','policy'])[['delta_L2','delta_high95_IoU','delta_Kmax_error']].mean().reset_index())
 sections['audit']=f'The independent path validates actual query-ID arrays and4096 context memberships, original fold/checkpoint assignments, feature hashes and no-gradient metadata for **{audit["runtime_forward_batches"]} actual forward batches**. It separately recomputes weighted field/localization/centroid/FPFN/paired/boundary metrics using independently implemented sums/CDF logic and reconstructs S1/S2 with scatter-add rather than the primary bincount path. **{audit["metric_checks"]} numerical checks passed**, maximum difference **{audit["maximum_metric_difference"]:.9g}**. All33 original target/checkpoint hashes were rechecked after computation. No fit, optimizer/backpropagation, weight update, new FE, target or external inference occurred.\n'
 sections['mechanisms']=md(pd.DataFrame(matrix)[['mechanism','measured_signature','classification','confounders','permitted_conclusion']])
 sections['resources']=f'Finite preregistered workload:52 checkpoint/source pairs,572 raw source-intervention fields, **{budget["forward_batches_exact"]} forward batches**, **{budget["raw_predictions_exact"]} raw point predictions**, of which{budget["additional_overlap_predictions"]} are extra overlap evaluations. Forty isolated sequential workers (20 replay,20 intervention), CPU deterministic two threads, batch512. No retry/configuration expansion after intervention results. Resource gates:16GiB workspace cap,20GiB freeE,2GiB freeC,3GiB available RAM and commit reserve. Measured worker costs and resources are in RESOURCE_ACCOUNTING.csv. Two early orchestration attempts stopped on missing prerequisite receipts before any inference; original logs are retained (prepare.log and preregister.log). Their prerequisites subsequently completed; no experiment or sealed inference code changed.\n'
 sections['limitations']='The five plates and thirteen sources were already exposed in E13/E14. Documentary plate grouping is not certified manufacturing-batch or scan-session independence. Millions of repeated point comparisons are not independent specimens; no confirmatory significance is claimed. Shift, overlap and CDF phase are each one prescribed intervention, not a response-surface search. FULL alternate context is sampling-only; no physical FULL extent reduction is implied. Oracle global features are nondeployable full-information inputs. NORM-P remains infeasible. Interior matching is approximate, with replacement, and residual geometry differences remain. The curvature and geometric ridge distances are representation proxies, not validated weld-toe radius or track measurements. Reduced jumps can suppress real numerical peaks, so continuity alone is insufficient. Source calibration/raw registration, hidden rear geometry, FE discretization and physical stress accuracy remain unresolved.\n'
 sections['future']='Retain both frozen models and both seeds as research comparators. A separately authorized next phase should freeze a deployment-observable feature/datum contract, isolate smaller feature blocks and context-sampling/ownership changes, and test any proposed inference policy on genuinely unused independently documented parent plates with recorded acquisition sessions. Require joint field L2, High95 FN/IoU, peak/Q95 amplitude and boundary/control continuity safeguards. Do not use additional coupons from these exposed plates or exposed Aalborg data as fresh independent validation. No production policy, neural retraining, new architecture, FE campaign or physical grinding recommendation is authorized by this audit.\n'
 absolute=df.assign(absolute_peak_error_MPa=lambda x:abs(x.pred_max_MPa-x.ref_max_MPa),absolute_Q95_error_MPa=lambda x:abs(x.Q95_error_MPa),variance_amplitude_ratio=lambda x:x.pred_std_MPa/x.ref_std_MPa);absmetrics=['absolute_peak_error_MPa','absolute_Q95_error_MPa','variance_amplitude_ratio'];absmacro=absolute.groupby(['model','seed','condition','policy','plate'])[absmetrics].mean().groupby(['model','seed','condition','policy']).mean().reset_index();table(R/'16_high95_localization/ABSOLUTE_AMPLITUDE_SEED_MACROS.csv',absmacro.to_dict('records'));sections['accuracy']+='\n## Absolute amplitude errors (avoid cancellation of signed biases)\n\n'+md(absmacro[absmacro.policy.isin(['S0','S1','S2'])])
 effects=[]
 for _,a in seeds[seeds.policy=='S2'].iterrows():
  for pa,pb in [('S0','S1'),('S1','S2'),('S0','S2')]:
   aa=seeds[(seeds.model==a.model)&(seeds.seed==a.seed)&(seeds.condition==a.condition)&(seeds.policy==pa)].iloc[0];bb=seeds[(seeds.model==a.model)&(seeds.seed==a.seed)&(seeds.condition==a.condition)&(seeds.policy==pb)].iloc[0];ca=continuity[(continuity.model==a.model)&(continuity.seed==a.seed)&(continuity.condition==a.condition)&(continuity.policy==pa)].iloc[0];cb=continuity[(continuity.model==a.model)&(continuity.seed==a.seed)&(continuity.condition==a.condition)&(continuity.policy==pb)].iloc[0];effects.append(dict(model=a.model,seed=int(a.seed),condition=a.condition,contrast=pb+' minus '+pa,identical_raw_cache=(pa=='S1' and pb=='S2'),delta_L2=float(bb.L2-aa.L2),delta_MAE_MPa=float(bb.MAE_MPa-aa.MAE_MPa),delta_high95_IoU=float(bb.high95_IoU-aa.high95_IoU),delta_boundary_jump_error_MPa=float(cb.mean_boundary_jump_error_MPa-ca.mean_boundary_jump_error_MPa),delta_Kmax_bias=float(bb.Kmax_error-aa.Kmax_error),FULL_boundary_is_proxy=a.condition=='FULL'))
 table(R/'17_mechanism_decomposition/AGGREGATION_EFFECTS_BY_SEED.csv',effects);sections['stitching']+='\n## Paired aggregation effects, both seeds\n\n'+md(pd.DataFrame(effects))
 sections['information']+='\n## Reused historical partial density control (no new inference)\n\n'+md(pd.read_csv(R/'10_density_controls/D0_MINUS_FULL_METRICS.csv'))
 sections['resources']+='\nA subsequent postprocessing attempt stopped before metric completion on a missing math import. The diagnostic log is retained as evaluate_e15_INITIAL_ERROR.log; only postprocessing resumed after the import correction, with no repeated neural forward passes or intervention changes.\n'
 headline='Historical FULL has no tile seam. Restricted-view boundary effects must be assessed against matched interior variation; the old FULL jump statistic is a reference-cut diagnostic. Oracle global-block and FULL sampling controls identify computational input sensitivities, while pure observation-information loss remains confounded. S1 versus S2 isolates aggregation weights; S0 versus overlap does not. Numerical continuity, field accuracy, localization and amplitude are reported jointly without selecting a favorable policy.\n'
 interpretation=[]
 for model in ['N1','N2']:
  fullrow=means[(means.model==model)&(means.condition=='FULL')&(means.policy=='S0')].iloc[0]
  for condition in ['X50','X43']:
   ss=means[(means.model==model)&(means.condition==condition)];base=ss[ss.policy=='S0'].iloc[0];orr=ss[ss.policy=='ORACLE'].iloc[0];uni=ss[ss.policy=='S1'].iloc[0];tent=ss[ss.policy=='S2'].iloc[0];cc=cmean[(cmean.model==model)&(cmean.condition==condition)];b0=cc[cc.policy=='S0'].iloc[0];b1=cc[cc.policy=='S1'].iloc[0];b2=cc[cc.policy=='S2'].iloc[0]
   interpretation.append(f'{model} {condition}: the joint oracle global-feature block changes L2 {base.L2:.7f} to {orr.L2:.7f} (matching FULL {fullrow.L2:.7f}) and High95 IoU {base.high95_IoU:.7f} to {orr.high95_IoU:.7f}. This is a controlled feature-block input effect at fixed visible neighborhoods/context IDs, with full-information statistics supplied deliberately; it cannot be presented as deployable partial observation or as an isolated one-channel normalization effect. Uniform overlap changes L2 by {(uni.L2/base.L2-1)*100:.4f}% and IoU by {uni.high95_IoU-base.high95_IoU:+.7f}; tent weighting changes L2 by {(tent.L2/base.L2-1)*100:.4f}% and IoU by {tent.high95_IoU-base.high95_IoU:+.7f}. Fixed original-boundary jump error changes from {b0.mean_boundary_jump_error_MPa:.6f} MPa to {b1.mean_boundary_jump_error_MPa:.6f} (S1) and {b2.mean_boundary_jump_error_MPa:.6f} (S2).')
 interpretation.append('The near-restoration of N1 FULL accuracy by the oracle block, together with much smaller field-score gains from overlap despite large seam-error reductions, identifies the supplied global representation block as a more consequential tested N1 input mechanism than the chosen stitching change. This comparison is descriptive across distinct interventions, not an additive causal variance decomposition. N2 exhibits a different accuracy/localization trade-off under the same oracle intervention. FULL S1/S2 are invariant to numerical roundoff, consistent with one shared context and no original seam. Neither inference policy is established as universally superior across seeds, sources, localization and amplitude metrics.')
